 events=[]
 for slot,(a,b) in enumerate(zip(old,new)):
  rm,ad=parts(a[2])-parts(b[2]),parts(b[2])-parts(a[2]);left=set(ad);paired=set()
  for x in sorted(rm):
   if left:
    y=min(left,key=lambda y:(HEAD[x]!=HEAD[y],y));left.remove(y);paired.update([x,y])
  for part in sorted(rm|ad):events.append(dict(boundary=slot,part=part,direction='remove' if part in rm else 'add',operation='SUBSTITUTE' if part in paired else 'DELETE' if part in rm else 'ADD'))
 return dict(marks=events,deletions=[],additions=[],quotes=[])
